:root {
  --ink: #08110c;
  --panel: rgba(9, 22, 16, 0.82);
  --panel-border: rgba(230, 193, 104, 0.32);
  --gold: #e6c168;
  --gold-bright: #ffe6a1;
  --gold-deep: #a87a2e;
  --cream: #f7efd9;
  --muted: #a9bca8;
  --green: #72d28a;
  --green-deep: #2f8d53;
  --red: #e2564c;
  --red-bright: #ff8a6a;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.5);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --joystick-size: 138px;
  --attack-size: 100px;
  --potion-size: 68px;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #06100b;
  color: var(--cream);
  font-family: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}

body {
  position: fixed;
  inset: 0;
}

#game-shell,
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

#game {
  display: block;
  touch-action: none;
  cursor: crosshair;
  background: #12281a;
}

.is-hidden {
  opacity: 0 !important;
  pointer-events: none !important;
  visibility: hidden !important;
}

/* ------------------------------- HUD ------------------------------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  padding:
    calc(12px + var(--safe-top))
    calc(12px + var(--safe-right))
    calc(12px + var(--safe-bottom))
    calc(12px + var(--safe-left));
  transition: opacity 220ms ease;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
}

.player-panel {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(400px, 56vw);
  min-width: 0;
  padding: 9px 13px 9px 9px;
  border: 1px solid var(--panel-border);
  border-radius: 15px;
  background:
    linear-gradient(130deg, rgba(28, 48, 34, 0.86), rgba(8, 18, 13, 0.88)),
    var(--panel);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}

.crest {
  flex: none;
  display: grid;
  place-items: center;
  width: 45px;
  height: 45px;
  border: 1px solid rgba(230, 193, 104, 0.55);
  border-radius: 12px;
  background:
    radial-gradient(circle at 35% 25%, rgba(255, 236, 176, 0.23), transparent 45%),
    linear-gradient(145deg, #273d2d, #0c1811);
  box-shadow: inset 0 0 16px rgba(230, 193, 104, 0.12);
}

.crest-mark {
  font-size: 22px;
  filter: drop-shadow(0 1px 2px #000);
  transform: rotate(-12deg);
}

.status-main {
  flex: 1;
  min-width: 0;
}

.status-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
  line-height: 1;
}

.player-name {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--gold);
  white-space: nowrap;
}

.hp-text {
  font-variant-numeric: tabular-nums;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #e8f4e3;
  opacity: 0.85;
  text-shadow: 0 1px 3px #000;
  white-space: nowrap;
}

.health-track {
  position: relative;
  height: 12px;
  overflow: hidden;
  border: 1px solid rgba(0, 0, 0, 0.55);
  border-radius: 7px;
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.045) 0 2px, transparent 2px 20px),
    #1a241c;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.65), 0 1px 0 rgba(255, 255, 255, 0.08);
}

.health-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: 5px;
  background: linear-gradient(180deg, #ff7a5c 0%, #e14b43 44%, #a5252b 100%);
  box-shadow: 0 0 12px rgba(240, 82, 64, 0.35), inset 0 1px 0 rgba(255, 220, 190, 0.5);
  transition: width 180ms ease-out, filter 180ms ease;
}

.health-fill.low {
  animation: low-health 900ms ease-in-out infinite;
}

.health-glint {
  position: absolute;
  inset: 1px 1px auto 1px;
  height: 3px;
  border-radius: 4px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.34), transparent);
  pointer-events: none;
}

@keyframes low-health {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.45); }
}

.objective-line {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 5px;
  line-height: 1;
  white-space: nowrap;
}

.objective-label {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.beast-pips {
  display: flex;
  gap: 4px;
}

.beast-pip {
  position: relative;
  width: 13px;
  height: 8px;
  border-radius: 2px 2px 4px 4px;
  background: linear-gradient(180deg, #d6c596, #8b7544);
  box-shadow: 0 1px 2px #000;
  transition: background 240ms ease, opacity 240ms ease, transform 240ms ease;
}

.beast-pip::before,
.beast-pip::after {
  content: "";
  position: absolute;
  top: -3px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: inherit;
}

.beast-pip::before { left: 0; }
.beast-pip::after { right: 0; }

.beast-pip.dead {
  opacity: 0.26;
  transform: scale(0.8) translateY(2px);
  background: #536456;
  box-shadow: none;
}

.beast-pip.dead::after {
  content: "×";
  top: -6px;
  right: -1px;
  width: auto;
  height: auto;
  background: none;
  color: #d8e2d5;
  font-size: 9px;
  font-weight: 800;
  line-height: 1;
}

.kill-count {
  margin-left: auto;
  font-size: 9px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
  color: var(--gold);
}

/* ----------------------------- Satchel ----------------------------- */

.satchel {
  flex: none;
  width: min(196px, 38vw);
  padding: 8px 9px 7px;
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  background:
    linear-gradient(150deg, rgba(30, 45, 30, 0.78), rgba(7, 16, 11, 0.88)),
    var(--panel);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(8px);
}

.satchel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2px 5px;
}

.satchel-title {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--gold);
}

.sound-btn {
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--cream);
  font-size: 11px;
  line-height: 1;
  cursor: pointer;
  opacity: 0.65;
  pointer-events: auto;
  transition: opacity 160ms ease, background 160ms ease;
}

.sound-btn:hover {
  opacity: 1;
  background: rgba(255, 255, 255, 0.08);
}

.satchel-row {
  display: flex;
  gap: 5px;
}

.inv-chip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  flex: 1;
  height: 26px;
  padding: 0 7px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.24);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.35);
}

.chip-icon {
  font-size: 13px;
  line-height: 1;
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.45));
}

.chip-value {
  overflow: hidden;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #f5e7bd;
  white-space: nowrap;
}

.relic-list {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  max-height: 42px;
  margin-top: 4px;
  overflow: hidden;
}

.relic-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  max-width: 100%;
  padding: 2px 5px;
  border: 1px solid rgba(230, 193, 104, 0.3);
  border-radius: 5px;
  background: rgba(230, 193, 104, 0.09);
  color: #ecdaa4;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
  animation: chip-in 280ms ease-out;
}

.relic-chip .relic-ico {
  font-size: 9px;
}

.relic-list:empty {
  display: none;
}

@keyframes chip-in {
  from { opacity: 0; transform: translateY(-3px) scale(0.92); }
  to { opacity: 1; transform: none; }
}

/* ------------------------------ Toast ------------------------------ */

.toast {
  position: absolute;
  top: calc(86px + var(--safe-top));
  left: 50%;
  max-width: min(440px, 82vw);
  padding: 9px 18px;
  border: 1px solid rgba(230, 193, 104, 0.45);
  border-radius: 100px;
  background: rgba(7, 18, 12, 0.9);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  color: var(--gold-bright);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(11px, 1.7vw, 14px);
  font-weight: 700;
  letter-spacing: 0.03em;
  text-align: center;
  white-space: nowrap;
  opacity: 0;
  transform: translate(-50%, -8px) scale(0.96);
  transition: opacity 200ms ease, transform 240ms cubic-bezier(0.2, 1.5, 0.5, 1);
  backdrop-filter: blur(6px);
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.desktop-hint {
  position: absolute;
  bottom: calc(15px + var(--safe-bottom));
  left: 50%;
  padding: 7px 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 100px;
  background: rgba(5, 13, 9, 0.62);
  color: rgba(230, 239, 225, 0.7);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  white-space: nowrap;
  transform: translateX(-50%);
  backdrop-filter: blur(5px);
}

.desktop-hint kbd {
  display: inline-block;
  min-width: 17px;
  margin: 0 1px;
  padding: 2px 5px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-bottom-color: rgba(0, 0, 0, 0.6);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  color: #f0e6c8;
  font-family: inherit;
  font-size: 8px;
  text-align: center;
}

.desktop-hint span {
  margin: 0 3px;
  opacity: 0.4;
}

/* ----------------------------- Controls ---------------------------- */

.controls {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  transition: opacity 220ms ease;
}

.joystick {
  position: absolute;
  left: calc(21px + var(--safe-left));
  bottom: calc(23px + var(--safe-bottom));
  width: var(--joystick-size);
  height: var(--joystick-size);
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  cursor: grab;
}

.joystick::before {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(230, 193, 104, 0.28);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 42%, rgba(80, 112, 78, 0.22), transparent 62%),
    rgba(5, 15, 10, 0.44);
  box-shadow:
    inset 0 0 28px rgba(0, 0, 0, 0.55),
    0 10px 30px rgba(0, 0, 0, 0.35),
    0 0 0 1px rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(5px);
}

.joystick-ring {
  position: absolute;
  inset: 1px;
  border: 1px dashed rgba(230, 193, 104, 0.16);
  border-radius: 50%;
}

.joystick-arrows {
  position: absolute;
  inset: 14px;
  color: rgba(230, 225, 200, 0.22);
  font-size: 8px;
  pointer-events: none;
}

.joystick-arrows span {
  position: absolute;
}

.joystick-arrows span:nth-child(1) { top: 0; left: 50%; transform: translateX(-50%); }
.joystick-arrows span:nth-child(2) { bottom: 0; left: 50%; transform: translateX(-50%); }
.joystick-arrows span:nth-child(3) { left: 0; top: 50%; transform: translateY(-50%); }
.joystick-arrows span:nth-child(4) { right: 0; top: 50%; transform: translateY(-50%); }

.joystick-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: 53px;
  height: 53px;
  border: 1px solid rgba(255, 231, 172, 0.45);
  border-radius: 50%;
  background:
    radial-gradient(circle at 36% 27%, rgba(255, 250, 220, 0.42), transparent 34%),
    linear-gradient(150deg, #65785e, #243526 58%, #101b13);
  box-shadow:
    0 8px 18px rgba(0, 0, 0, 0.5),
    inset 0 1px 1px rgba(255, 255, 255, 0.34),
    inset 0 -3px 8px rgba(0, 0, 0, 0.4);
  transform: translate(-50%, -50%);
  will-change: transform;
}

.joystick-knob span {
  width: 12px;
  height: 12px;
  border: 1px solid rgba(230, 193, 104, 0.35);
  border-radius: 50%;
  background: rgba(230, 193, 104, 0.15);
}

.joystick.active .joystick-knob {
  box-shadow:
    0 6px 14px rgba(0, 0, 0, 0.55),
    0 0 22px rgba(230, 193, 104, 0.22),
    inset 0 1px 1px rgba(255, 255, 255, 0.4);
}

.action-cluster {
  position: absolute;
  right: calc(20px + var(--safe-right));
  bottom: calc(24px + var(--safe-bottom));
  width: 190px;
  height: 190px;
  pointer-events: none;
}

.game-btn {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid rgba(255, 232, 172, 0.42);
  border-radius: 50%;
  color: #fff9e9;
  font-family: inherit;
  line-height: 1;
  pointer-events: auto;
  touch-action: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform 90ms ease, filter 120ms ease, opacity 180ms ease;
}

.game-btn:active,
.game-btn.pressed {
  transform: scale(0.92);
  filter: brightness(1.17);
}

.btn-glyph {
  display: block;
  font-size: 23px;
  line-height: 1;
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.55));
}

.btn-word {
  margin-top: 4px;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.13em;
  text-shadow: 0 1px 3px #000;
  opacity: 0.9;
}

.attack-btn {
  right: 0;
  bottom: 0;
  width: var(--attack-size);
  height: var(--attack-size);
  border-color: rgba(255, 214, 150, 0.55);
  background:
    radial-gradient(circle at 36% 26%, rgba(255, 222, 160, 0.24), transparent 35%),
    linear-gradient(150deg, #9d3b32, #5b1d22 62%, #2b0d12);
  box-shadow:
    0 12px 30px rgba(0, 0, 0, 0.46),
    0 0 0 6px rgba(157, 59, 50, 0.12),
    inset 0 2px 2px rgba(255, 210, 170, 0.25),
    inset 0 -8px 18px rgba(0, 0, 0, 0.4);
}

.attack-btn .sword-glyph {
  font-size: 33px;
}

.attack-btn::after {
  content: "";
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(255, 207, 139, 0.16);
  border-radius: 50%;
  pointer-events: none;
}

.attack-swoosh {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  border-top: 2px solid rgba(255, 239, 203, 0.38);
  border-right: 2px solid rgba(255, 239, 203, 0.38);
  border-radius: 0 100% 0 0;
  transform: rotate(-8deg);
  pointer-events: none;
}

.potion-btn {
  right: 105px;
  bottom: 12px;
  width: var(--potion-size);
  height: var(--potion-size);
  border-color: rgba(160, 240, 170, 0.4);
  background:
    radial-gradient(circle at 36% 26%, rgba(205, 255, 205, 0.25), transparent 35%),
    linear-gradient(150deg, #317249, #123c28 64%, #071d12);
  box-shadow:
    0 9px 22px rgba(0, 0, 0, 0.4),
    inset 0 2px 2px rgba(210, 255, 210, 0.2),
    inset 0 -6px 14px rgba(0, 0, 0, 0.35);
}

.potion-btn .btn-glyph {
  font-size: 22px;
}

.potion-btn.empty {
  opacity: 0.38;
  filter: grayscale(0.75);
}

.btn-badge {
  position: absolute;
  top: -4px;
  right: -2px;
  display: grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 20px;
  background: linear-gradient(180deg, #f6e3a4, #c79d4a);
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.4);
  color: #2b210d;
  font-size: 10px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}

.interact-btn {
  right: 22px;
  bottom: 112px;
  width: 88px;
  height: 44px;
  flex-direction: row;
  gap: 5px;
  border-radius: 100px;
  border-color: rgba(255, 230, 164, 0.62);
  background:
    linear-gradient(160deg, rgba(255, 240, 195, 0.28), transparent 44%),
    linear-gradient(150deg, #a9853f, #6d5126 66%, #2c200d);
  box-shadow:
    0 8px 20px rgba(0, 0, 0, 0.42),
    0 0 22px rgba(230, 193, 104, 0.22),
    inset 0 1px 1px rgba(255, 250, 220, 0.32);
  opacity: 0;
  transform: translateY(8px) scale(0.92);
  visibility: hidden;
  transition: opacity 180ms ease, transform 220ms cubic-bezier(0.2, 1.5, 0.5, 1), visibility 180ms;
  animation: interact-pulse 1.4s ease-in-out infinite;
}

.interact-btn.visible {
  opacity: 1;
  transform: none;
  visibility: visible;
}

.interact-btn .btn-glyph {
  font-size: 16px;
}

.interact-btn .btn-word {
  margin: 0;
  font-size: 8px;
}

@keyframes interact-pulse {
  0%, 100% { box-shadow: 0 8px 20px rgba(0, 0, 0, 0.42), 0 0 14px rgba(230, 193, 104, 0.18); }
  50% { box-shadow: 0 8px 20px rgba(0, 0, 0, 0.42), 0 0 28px rgba(230, 193, 104, 0.46); }
}

/* ----------------------------- Overlays ---------------------------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding:
    calc(22px + var(--safe-top))
    calc(18px + var(--safe-right))
    calc(22px + var(--safe-bottom))
    calc(18px + var(--safe-left));
  transition: opacity 260ms ease, visibility 260ms;
}

.menu-overlay {
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 16%, rgba(95, 136, 78, 0.2), transparent 46%),
    linear-gradient(180deg, rgba(4, 12, 8, 0.45), rgba(3, 9, 5, 0.84) 65%, rgba(2, 7, 4, 0.96));
}

.menu-vignette {
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(circle at 50% 46%, transparent 24%, rgba(0, 0, 0, 0.52) 88%),
    repeating-linear-gradient(115deg, transparent 0 4px, rgba(255, 255, 255, 0.012) 4px 5px);
  pointer-events: none;
}

.menu-card {
  position: relative;
  width: min(590px, 94vw);
  max-height: 100%;
  padding: clamp(18px, 4vh, 38px) clamp(18px, 4vw, 48px);
  overflow-y: auto;
  text-align: center;
  border: 1px solid rgba(230, 193, 104, 0.28);
  border-radius: 24px;
  background:
    linear-gradient(150deg, rgba(23, 42, 29, 0.9), rgba(6, 15, 10, 0.93)),
    rgba(8, 18, 12, 0.9);
  box-shadow:
    0 40px 100px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    inset 0 0 80px rgba(73, 105, 65, 0.12);
  backdrop-filter: blur(12px) saturate(1.05);
  scrollbar-width: none;
}

.menu-card::-webkit-scrollbar {
  display: none;
}

.eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 0 0 10px;
  color: var(--gold);
  font-size: clamp(8px, 1.2vw, 10px);
  font-weight: 800;
  letter-spacing: 0.28em;
  line-height: 1.3;
}

.eyebrow span {
  width: clamp(20px, 5vw, 45px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(230, 193, 104, 0.7));
}

.eyebrow span:last-child {
  background: linear-gradient(90deg, rgba(230, 193, 104, 0.7), transparent);
}

.eyebrow.danger {
  color: #e88b77;
}

.eyebrow.danger span {
  background: linear-gradient(90deg, transparent, rgba(232, 139, 119, 0.7));
}

.eyebrow.danger span:last-child {
  background: linear-gradient(90deg, rgba(232, 139, 119, 0.7), transparent);
}

.game-title {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(42px, 9.5vw, 83px);
  font-weight: 700;
  line-height: 0.88;
  letter-spacing: 0.035em;
  color: #f8edc9;
  text-shadow:
    0 2px 0 #3e2c12,
    0 8px 30px rgba(0, 0, 0, 0.6),
    0 0 60px rgba(230, 193, 104, 0.13);
}

.game-title span {
  color: var(--gold);
}

.subtitle {
  margin: 16px auto 0;
  max-width: 430px;
  color: #c7d2be;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(12px, 1.8vw, 15px);
  font-style: italic;
  line-height: 1.55;
}

.menu-controls {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin: clamp(18px, 3.2vh, 28px) 0 clamp(18px, 3vh, 26px);
}

.control-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 11px 6px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 11px;
  background: rgba(0, 0, 0, 0.2);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.tile-icon {
  font-size: clamp(17px, 2.6vw, 22px);
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.55));
}

.control-tile b {
  display: block;
  color: #efe5c7;
  font-size: clamp(9px, 1.2vw, 11px);
  letter-spacing: 0.04em;
}

.control-tile small {
  display: block;
  margin-top: 2px;
  color: #91a58f;
  font-size: clamp(7px, 0.9vw, 9px);
  line-height: 1.3;
}

.primary-btn {
  position: relative;
  min-width: 190px;
  padding: 14px 38px;
  overflow: hidden;
  border: 1px solid rgba(255, 237, 189, 0.72);
  border-radius: 100px;
  background:
    linear-gradient(180deg, rgba(255, 246, 210, 0.42), transparent 50%),
    linear-gradient(180deg, #f0ce74, #c4933b 55%, #8e6424);
  box-shadow:
    0 10px 26px rgba(0, 0, 0, 0.4),
    0 0 34px rgba(230, 193, 104, 0.2),
    inset 0 1px 1px rgba(255, 255, 255, 0.55),
    inset 0 -3px 7px rgba(78, 48, 10, 0.35);
  color: #2f230b;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(15px, 2vw, 18px);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-shadow: 0 1px 0 rgba(255, 241, 190, 0.45);
  cursor: pointer;
  touch-action: manipulation;
  transition: transform 120ms ease, filter 120ms ease, box-shadow 160ms ease;
}

.primary-btn::after {
  content: "";
  position: absolute;
  top: -60%;
  left: -40%;
  width: 30%;
  height: 220%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.32), transparent);
  transform: rotate(18deg);
  animation: btn-shine 4.6s ease-in-out infinite;
}

.primary-btn:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
  box-shadow:
    0 14px 32px rgba(0, 0, 0, 0.45),
    0 0 44px rgba(230, 193, 104, 0.3),
    inset 0 1px 1px rgba(255, 255, 255, 0.6);
}

.primary-btn:active {
  transform: translateY(1px) scale(0.985);
}

@keyframes btn-shine {
  0%, 62% { left: -40%; opacity: 0; }
  68% { opacity: 1; }
  80%, 100% { left: 130%; opacity: 0; }
}

.menu-footnote {
  margin: 14px 0 0;
  color: #7f947f;
  font-size: clamp(8px, 1.1vw, 10px);
  letter-spacing: 0.05em;
}

.result-overlay {
  background:
    radial-gradient(ellipse at 50% 35%, rgba(59, 91, 56, 0.28), transparent 55%),
    rgba(3, 9, 5, 0.84);
  backdrop-filter: blur(4px);
}

.result-card {
  width: min(560px, 94vw);
  padding: clamp(24px, 4.5vh, 44px) clamp(20px, 4vw, 48px);
  border: 1px solid rgba(230, 193, 104, 0.38);
  border-radius: 22px;
  background:
    linear-gradient(155deg, rgba(26, 46, 31, 0.94), rgba(5, 14, 9, 0.96)),
    var(--panel);
  box-shadow:
    0 36px 90px rgba(0, 0, 0, 0.62),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 0 80px rgba(230, 193, 104, 0.06);
  text-align: center;
  animation: result-in 460ms cubic-bezier(0.18, 1.2, 0.4, 1);
}

.defeat-card {
  border-color: rgba(226, 86, 76, 0.4);
  background:
    linear-gradient(155deg, rgba(48, 28, 27, 0.94), rgba(12, 7, 8, 0.97)),
    var(--panel);
  box-shadow:
    0 36px 90px rgba(0, 0, 0, 0.66),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 0 80px rgba(226, 86, 76, 0.07);
}

@keyframes result-in {
  from { opacity: 0; transform: translateY(14px) scale(0.96); }
  to { opacity: 1; transform: none; }
}

.result-title {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(40px, 8vw, 64px);
  line-height: 1;
  letter-spacing: 0.08em;
  color: var(--gold-bright);
  text-shadow: 0 2px 0 #4c3713, 0 10px 36px rgba(0, 0, 0, 0.6), 0 0 50px rgba(230, 193, 104, 0.2);
}

.defeat-card .result-title {
  color: #f19983;
  text-shadow: 0 2px 0 #4b1e1b, 0 10px 36px rgba(0, 0, 0, 0.6), 0 0 50px rgba(226, 86, 76, 0.16);
}

.result-copy {
  margin: 15px auto 0;
  max-width: 420px;
  color: #bfc9b6;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(12px, 1.7vw, 14px);
  font-style: italic;
  line-height: 1.55;
}

.result-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin: clamp(18px, 3vh, 26px) 0;
  padding: 12px 6px;
  border-top: 1px solid rgba(230, 193, 104, 0.18);
  border-bottom: 1px solid rgba(230, 193, 104, 0.18);
}

.defeat-card .result-stats {
  grid-template-columns: repeat(3, 1fr);
  border-color: rgba(226, 86, 76, 0.16);
}

.result-stats div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.result-stats span {
  overflow: hidden;
  color: #f8ecc7;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(19px, 3vw, 27px);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
}

.result-stats small {
  color: #83957f;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.victory-loot {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 5px;
  margin: -8px 0 20px;
}

.victory-loot:empty {
  display: none;
}

.loot-pill {
  padding: 4px 9px;
  border: 1px solid rgba(230, 193, 104, 0.24);
  border-radius: 100px;
  background: rgba(230, 193, 104, 0.08);
  color: #e9d79f;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

/* --------------------------- Rotate hint --------------------------- */

.rotate-hint {
  position: absolute;
  bottom: calc(14px + var(--safe-bottom));
  left: 50%;
  z-index: 6;
  display: none;
  padding: 7px 14px;
  border: 1px solid rgba(230, 193, 104, 0.2);
  border-radius: 100px;
  background: rgba(4, 12, 8, 0.7);
  color: #b7c5ae;
  font-size: 9px;
  letter-spacing: 0.04em;
  transform: translateX(-50%);
  backdrop-filter: blur(6px);
}

.rotate-hint span {
  display: inline-block;
  margin-right: 4px;
  color: var(--gold);
  font-size: 13px;
}

/* ----------------------------- Responsive -------------------------- */

@media (max-width: 760px) {
  :root {
    --joystick-size: 122px;
    --attack-size: 90px;
    --potion-size: 62px;
  }

  .hud {
    padding-top: calc(9px + var(--safe-top));
    padding-left: calc(9px + var(--safe-left));
    padding-right: calc(9px + var(--safe-right));
  }

  .player-panel {
    width: min(310px, 61vw);
    gap: 8px;
    padding: 7px 9px 7px 7px;
    border-radius: 13px;
  }

  .crest {
    width: 37px;
    height: 37px;
    border-radius: 10px;
  }

  .crest-mark {
    font-size: 18px;
  }

  .player-name {
    font-size: 10px;
  }

  .hp-text {
    font-size: 9px;
  }

  .health-track {
    height: 10px;
  }

  .objective-line {
    margin-top: 4px;
  }

  .objective-label {
    font-size: 7px;
  }

  .beast-pip {
    width: 11px;
    height: 7px;
  }

  .kill-count {
    font-size: 8px;
  }

  .satchel {
    width: min(132px, 36vw);
    padding: 6px 7px 6px;
    border-radius: 11px;
  }

  .satchel-head {
    padding-bottom: 3px;
  }

  .satchel-title {
    font-size: 7px;
  }

  .inv-chip {
    height: 22px;
    padding: 0 4px;
    gap: 3px;
    border-radius: 6px;
  }

  .chip-icon {
    font-size: 11px;
  }

  .chip-value {
    font-size: 9px;
  }

  .relic-list {
    max-height: 16px;
    margin-top: 3px;
    flex-wrap: nowrap;
    overflow: hidden;
  }

  .relic-chip {
    padding: 1px 4px;
    font-size: 7px;
  }

  .relic-chip .relic-name {
    display: none;
  }

  .relic-chip .relic-ico {
    font-size: 8px;
  }

  .toast {
    top: calc(77px + var(--safe-top));
    padding: 7px 13px;
    font-size: 10px;
  }

  .desktop-hint {
    display: none;
  }

  .joystick {
    left: calc(14px + var(--safe-left));
    bottom: calc(16px + var(--safe-bottom));
  }

  .joystick-knob {
    width: 47px;
    height: 47px;
  }

  .action-cluster {
    right: calc(14px + var(--safe-right));
    bottom: calc(16px + var(--safe-bottom));
    width: 170px;
    height: 170px;
  }

  .potion-btn {
    right: 91px;
    bottom: 5px;
  }

  .interact-btn {
    right: 10px;
    bottom: 98px;
    width: 80px;
    height: 40px;
  }

  .attack-btn .sword-glyph {
    font-size: 29px;
  }

  .btn-word {
    font-size: 6px;
  }

  .menu-card {
    border-radius: 19px;
  }

  .menu-controls {
    grid-template-columns: repeat(2, 1fr);
    max-width: 340px;
    margin-left: auto;
    margin-right: auto;
  }

  .control-tile {
    flex-direction: row;
    justify-content: flex-start;
    text-align: left;
    padding: 8px 10px;
  }

  .control-tile span:last-child {
    display: flex;
    flex-direction: column;
  }

  .control-tile small {
    margin-top: 1px;
  }

  .result-stats span {
    font-size: 20px;
  }
}

@media (max-width: 420px) {
  .player-panel {
    width: 64vw;
  }

  .satchel {
    width: 33vw;
  }

  .relic-chip .relic-name {
    display: none;
  }
}

@media (max-height: 560px) and (orientation: landscape) {
  :root {
    --joystick-size: 104px;
    --attack-size: 78px;
    --potion-size: 54px;
  }

  .hud {
    padding-top: calc(6px + var(--safe-top));
  }

  .player-panel {
    width: min(310px, 44vw);
    padding: 5px 8px 5px 6px;
  }

  .crest {
    width: 32px;
    height: 32px;
  }

  .crest-mark {
    font-size: 16px;
  }

  .satchel {
    width: min(155px, 26vw);
  }

  .satchel-row {
    gap: 3px;
