    const y = 1120 - t * 700;
    g.fillStyle = rng() > 0.5 ? 'rgba(150, 137, 109, 0.34)' : 'rgba(64, 58, 43, 0.34)';
    g.beginPath();
    g.ellipse(x, y, 2.2 + rng() * 5.5, 1.5 + rng() * 3.7, rng() * TAU, 0, TAU);
    g.fill();
  }

  // Pond.
  const pond = POND;
  g.save();
  g.translate(pond.x, pond.y);
  g.fillStyle = 'rgba(45, 50, 29, 0.85)';
  g.beginPath();
  g.ellipse(0, 0, pond.rx + 9, pond.ry + 8, 0, 0, TAU);
  g.fill();
  const water = g.createLinearGradient(0, -pond.ry, 0, pond.ry);
  water.addColorStop(0, '#285557');
  water.addColorStop(0.5, '#1f5351');
  water.addColorStop(1, '#123a39');
  g.fillStyle = water;
  g.beginPath();
  g.ellipse(0, 0, pond.rx, pond.ry, 0, 0, TAU);
  g.fill();

  g.strokeStyle = 'rgba(125, 185, 163, 0.2)';
  g.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    g.beginPath();
    g.ellipse(0, 0, pond.rx - 18 - i * 13, pond.ry - 13 - i * 8, 0, Math.PI * (0.11 + i * 0.07), Math.PI * (0.85 + i * 0.03));
    g.stroke();
  }

  for (let i = 0; i < 5; i++) {
    const lx = -53 + rng() * 108;
    const ly = -34 + rng() * 66;
    g.fillStyle = i % 2 ? '#3e6a3e' : '#56814a';
    g.beginPath();
    g.ellipse(lx, ly, 9 + rng() * 9, 5 + rng() * 5, rng() * TAU, 0, TAU);
    g.fill();
  }
  g.restore();

  // Dirt ruin around the chest.
  const ruin = g.createRadialGradient(CHEST_SPAWN.x, CHEST_SPAWN.y, 18, CHEST_SPAWN.x, CHEST_SPAWN.y, 160);
  ruin.addColorStop(0, 'rgba(137, 119, 82, 0.33)');
  ruin.addColorStop(0.62, 'rgba(119, 103, 70, 0.17)');
  ruin.addColorStop(1, 'rgba(119, 103, 70, 0)');
  g.fillStyle = ruin;
  g.beginPath();
  g.arc(CHEST_SPAWN.x, CHEST_SPAWN.y, 160, 0, TAU);
  g.fill();

  // Ruined flagstones.
  for (const stone of layout.ruinStones) {
    g.save();
    g.translate(stone.x, stone.y);
    g.rotate(stone.a + 0.4);
    g.fillStyle = `rgba(111, 112, 94, ${0.22 + stone.s * 0.2})`;
    g.beginPath();
    g.ellipse(0, 0, 10 + stone.s * 12, 5 + stone.s * 6, 0, 0, TAU);
    g.fill();
    g.restore();
  }

  // Grass blades and tiny ground detail.
  for (let i = 0; i < 1500; i++) {
    const x = rng() * WORLD.w;
    const y = rng() * WORLD.h;
    const h = 1.5 + rng() * 4.5;
    g.strokeStyle = rng() > 0.5 ? 'rgba(94, 137, 72, 0.34)' : 'rgba(33, 75, 41, 0.42)';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(x, y);
    g.quadraticCurveTo(x + (rng() - 0.5) * 3, y - h * 0.6, x + (rng() - 0.5) * 5, y - h);
    g.stroke();
  }

  // Fallen leaves.
  for (let i = 0; i < 220; i++) {
    const x = rng() * WORLD.w;
    const y = rng() * WORLD.h;
    g.save();
    g.translate(x, y);
    g.rotate(rng() * TAU);
    g.fillStyle = pick(['rgba(128, 93, 49, 0.3)', 'rgba(156, 113, 50, 0.24)', 'rgba(84, 108, 48, 0.28)', 'rgba(112, 68, 43, 0.25)']);
    g.beginPath();
    g.ellipse(0, 0, 1.2 + rng() * 3.2, 0.8 + rng() * 1.5, 0, 0, TAU);
    g.fill();
    g.restore();
  }

  // Wildflowers.
  for (let i = 0; i < 95; i++) {
    const x = rng() * WORLD.w;
    const y = rng() * WORLD.h;
    if (Math.hypot((x - POND.x) / POND.rx, (y - POND.y) / POND.ry) < 1.12) continue;
    const color = pick(['rgba(236, 224, 170, 0.6)', 'rgba(197, 161, 217, 0.55)', 'rgba(230, 192, 116, 0.58)', 'rgba(153, 193, 216, 0.4)']);
    g.fillStyle = color;
    g.beginPath();
    g.arc(x, y, 1.1 + rng() * 2.1, 0, TAU);
    g.fill();
    if (rng() > 0.45) {
      g.fillStyle = 'rgba(255, 250, 214, 0.65)';
      g.beginPath();
      g.arc(x, y, 0.6, 0, TAU);
      g.fill();
    }
  }

  // Shrubs baked into the terrain.
  for (const b of layout.bushes) {
    g.save();
    g.translate(b.x, b.y);
    g.scale(b.s, b.s);
    g.fillStyle = 'rgba(6, 22, 13, 0.25)';
    g.beginPath();
    g.ellipse(2, 6, 17, 7, 0, 0, TAU);
    g.fill();
    const colors = ['#315636', '#3d6940', '#4c7a47'];
    for (let i = 0; i < 5; i++) {
      g.fillStyle = colors[i % colors.length];
      g.beginPath();
      g.arc(-10 + i * 5, -4 + Math.sin(i * 2 + b.seed) * 4, 6 + (i % 3) * 2, 0, TAU);
      g.fill();
    }
    g.restore();
  }

  // Dark, painted world edge.
  const edge = 110;
  const top = g.createLinearGradient(0, 0, 0, edge);
  top.addColorStop(0, 'rgba(4, 13, 8, 0.62)');
  top.addColorStop(1, 'rgba(4, 13, 8, 0)');
  g.fillStyle = top;
  g.fillRect(0, 0, WORLD.w, edge);
  const bottom = g.createLinearGradient(0, WORLD.h, 0, WORLD.h - edge);
  bottom.addColorStop(0, 'rgba(3, 10, 6, 0.6)');
  bottom.addColorStop(1, 'rgba(3, 10, 6, 0)');
  g.fillStyle = bottom;
  g.fillRect(0, WORLD.h - edge, WORLD.w, edge);
  const left = g.createLinearGradient(0, 0, edge, 0);
  left.addColorStop(0, 'rgba(4, 13, 8, 0.56)');
  left.addColorStop(1, 'rgba(4, 13, 8, 0)');
  g.fillStyle = left;
  g.fillRect(0, 0, edge, WORLD.h);
  const right = g.createLinearGradient(WORLD.w, 0, WORLD.w - edge, 0);
  right.addColorStop(0, 'rgba(4, 13, 8, 0.56)');
  right.addColorStop(1, 'rgba(4, 13, 8, 0)');
  g.fillStyle = right;
  g.fillRect(WORLD.w - edge, 0, edge, WORLD.h);

  return c;
}

const groundCanvas = buildGroundCanvas(worldLayout);

// ------------------------------------------------------------ global state

const game = {
  mode: 'menu',
  time: 0,
  runStart: 0,
  overlayDelay: 0,
  damageFlash: 0,
  victoryFlash: 0,
  hintTimer: 0,
  player: null,
  enemies: [],
  pickups: [],
  drops: [],
  particles: [],
  floaters: [],
  slashes: [],
  leaves: [],
  fireflies: [],
  trees: worldLayout.trees,
  rocks: worldLayout.rocks,
  chest: null,
  inventory: null,
  stats: null,
  chestReward: null,
  camera: {
    x: PLAYER_SPAWN.x,
    y: PLAYER_SPAWN.y,
    zoom: 1,
    shake: 0,
    shakeX: 0,
    shakeY: 0
  },
  view: { w: 1, h: 1, dpr: 1 },
  input: {
    keys: new Set(),
    joyX: 0,
    joyY: 0,
    joyActive: false,
    joyPointer: null,
    attackHeld: false,
    lastPotionAt: -10
  }
};

content.text:
Now logic.js. Include resetGame, createEnemies, particles, floaters, collisions, updates, combat, pickups, chest, camera, ambient, victory/death. Must reference DOM functions not yet defined at parse but runtime fine.

Let's plan methods:

```
function resetGame() {
  game.mode='menu'? no, reset leaves mode unchanged? Better resetWorld and set mode. Called before start and menu init. 
  game.time=0; ...
  game.player=createPlayer();
  game.enemies=ENEMY_SPAWNS.map(createEnemy)
  game.pickups=...
  game.chest={x,y,opened:false,openT:0,glow...}
  game.inventory={...}
  game.stats={kills,damageDealt,damageTaken,potionsUsed,startTime:0}
  ...
  game.leaves=createLeaves(); fireflies...
  camera set...
  resetHud? call updateHud(true) at end, but DOM may not be ready? main defines. It's loaded before init. Fine.
}
```
- `startRun()` maybe in main: resetGame(); game.mode='playing'; game.runStart=0; show... 
- `resetGame` should not set mode? Let caller. But `startGame` can. For initial menu, resetGame sets player and world, mode remains menu.
- `game.time=0` on reset.
- `game.stats.startedAt=0`.

Create player:
```
{
 x,y,r,hp,maxHp,facing:-PI/2, speed,... attackCooldown:0, attackTimer:0, hitDone:true, invuln:0, hurtFlash:0, knockVX:0, knockVY:0, moving:false, walkPhase:0, dead:false, deathT:0, trailTimer:0
}
```
- facing upwards -> -PI/2 (since 0=right, up=-PI/2). Good.

Create enemy:
```
const t=ENEMY_TYPES[type]; 
{
 id,type,name,short, x,y,homeX,homeY, r, hp,maxHp, speed, damage, range, aggro, windup, cooldown,
 state:'idle', stateT:rand, attackCooldown: rand(0,0.5), facing: angle to player,
 wanderAngle, wanderT, hitFlash:0, knockVX:0, knockVY:0, dead:false, deathT:0,
 aggroed:false, windupTotal, strikeDone:false, alertT:0
}
```
- State names: idle, chase, windup, recover, retreat.
- `stateT` for idle wander, recover.
- `attackCooldown` initial random 0.3-1.
- Enemy y positions etc.

Collision:
```
function collidesAt(x,y,r){
 if (x < WORLD.margin+r || ... ) return true;
 for trees: dx... if dist < r + t.collisionR return true;
 for rocks...
 if (!game.chest.opened? maybe always) chest collision radius 19
 if (dist to campfire < 19+r) return true;
 if (Math.hypot((x-POND.x)/(POND.collisionR+r), (y-POND.y)/(POND.collisionR+r)) < 1) return true;
 // tent: rectangle? approximate circle radius 30 at (TENT.x,TENT.y+10)
 if (dist to TENT < 30+r) return true;
 return false;
}
```
- For chest after opened still collides. Good.
- `moveEntity(e, dx, dy, r)` axis separated. Use substeps if movement large? dt max 0.05 speed 210 -> 10px, fine. knockback 300 -> 15px. Fine.
- World bounds margin maybe allow edge. Tree border at 40; bounds 30.

Particles:
```
function spawnParticles(x,y,count,opts)
```
- opts colors array, speed min/max, life, size, gravity, kind. Each particle {x,y,vx,vy,life,maxLife,size,color,gravity,drag,glow}.
- updateParticles(dt): position, life, gravity, drag; filter.
- Floaters: `addFloater(x,y,text,color,size)`; update float up.
- Slashes: effect objects {x,y,angle,t,life,radius,color,type}. Update and draw.

- Damage floats: at enemy position y-25. Random x offset.

- Ambient:
  - `createLeaves()` 30 with random world positions, velocity, phase.
  - update leaves: x += wind + sin; y +=; wrap.
  - fireflies 26 with base points around pond/camp plus random; orbit angle speed radius; update time.
- Add little glowing firefly particles in render directly.

Update player:
```
function updatePlayer(dt) {
 const p = game.player;
 if (!p || p.dead) return;
 const keys=game.input.keys;
 let mx = ...
 let my = ...
 const joy = game.input;
 mx += joy.joyX; my += joy.joyY;
 const len = Math.hypot(mx,my);
 if (len > 1) {mx/=len; my/=len;}
 const moving = len > 0.1;
 p.moving = moving;
 if (moving) {
  p.facing = lerpAngle(p.facing, Math.atan2(my,mx), 1 - Math.exp(-dt*18));
  p.walkPhase += dt * 11;
  moveEntity(p, mx*p.speed*dt, my*p.speed*dt, p.r);
 } else { p.walkPhase += dt*2; }
 // knockback
 if (Math.abs(p.knockVX)>1 || ...) { moveEntity(...); decay }
 p.attackCooldown = max...
 p.invuln = ...
 p.hurtFlash...
 if (p.attackTimer > 0) {
   p.attackTimer -= dt;
   if (!p.hitDone && p.attackTimer <= PLAYER_BASE.attackAnim * 0.52) performSwordHit();
   if (p.attackTimer <=0) p.attackTimer=0;
 }
 if (game.input.attackHeld && p.attackCooldown<=0) tryAttack();
 // footstep dust occasionally? if moving and Math.floor(walkPhase) changed? maybe skip.
}
```
- Careful: if p.attackTimer gets 0 after decrement while hit not done? The threshold 0.156 > 0, so it triggers. Good.
- `tryAttack` checks mode.
- Auto-target nearest within 145. maybe only if in front? It can feel okay to auto face nearest. Use 155. Also aggro that enemy. Fine.
- attackTimer starts at PLAYER_BASE.attackAnim (0.3); hit threshold = 0.3*0.52=0.156. Good.
- `p.hitDone=false`.

Sword hit:
```
const p=game.player;
p.hitDone=true;
const reach = PLAYER_BASE.attackRange;
let hits=0;
for (const e of game.enemies) {
 if (e.dead) continue;
 const d=dist(p,e);
 if (d - e.r <= reach && Math.abs(angleDelta(p.facing, angleTo(p.x,p.y,e.x,e.y))) < PLAYER_BASE.attackArc) {
   const crit = Math.random()<0.13;
   let dmg = base + inv.swordBonus + randInt(-2,5);
   if (crit) dmg=Math.round(dmg*1.7);
   damageEnemy(e,dmg, angleTo(p,e), crit);
   hits++;
 }
}
if (hits>0) { camera shake; Sound play hit; } else maybe no sound (swing already).
```
- Reach: d - e.r <= 112 means center distance < 127 for normal. Good. Cone half angle 1.16 (~66°) maybe total 132° wide, very forgiving. Fine.
- `damageEnemy`:
```
e.hp = max(0,e.hp-dmg);
e.hitFlash=.16; e.alertT= 4;
e.knockVX += cos(a)*230; e.knockVY += sin(a)*230;
game.stats.damageDealt += dmg;
addFloater(e.x+rand(-6,6), e.y-e.r-14, (crit?'CRIT ':'')+dmg, crit?'#ffd76e':'#fff1c3', crit?18:14);
spawnHitParticles(e.x, e.y, crit?16:9, angle)
Sound.play(crit?'crit':'hit');
camera.shake = max(camera.shake, crit?0.44:0.24)
if hp<=0 killEnemy
else set state? Keep as is. Enemy if idle becomes chase:
  if (e.state==='idle') e.state='chase';
```
- `killEnemy`:
```
e.dead=true; e.deathT=0; game.stats.kills++;
spawnParticles...
spawn gold drops...
Sound.play('enemyDown');
showToast(`${e.name} slain`, '✦')? Could be annoying. Maybe after each kill show "Mire Goblin slain — 2 beasts remain". Good.
updateHud...
if all dead -> triggerVictory()
```
- `e.hp` may be 0.
- Gold drops: split total? `count=randInt(3,5); each value = max(1, round(randInt(goldMin,goldMax)/2))`. Or assign total. Use total = randInt(goldMin,goldMax), count=3, distribute. Each drop gets value. Some remainder. Fine.
- Create drop with physics: angle random, speed 80-180, z? We only have 2D. Draw coins. It will scatter around and settle; use vx,vy, friction and bob.
- Add `drops.push({x,y,vx,vy,value,life:0,settled:false,phase:rand})`.
- Update drops: 
  - age += dt; vx *= drag; position; if speed<10 then settled.
  - if player alive and (age>0.35) and (dist<150 || game.mode==='victory'): accelerate toward player: dir*speed (300+). If dist<20 collect.
  - collect: add gold, stats? no; sound coin (maybe throttle), floater; updateHud; remove.
  - If mode victory, player still at death spot. Good.
- drops should be auto-collected during victory before overlay? overlay may come after 1.25s. Magnet speed 420, from up to 200 away -> <0.5s. Great.
- `triggerVictory`: if mode === 'playing' (or maybe after last kill) set mode='victory', overlayDelay=1.4, stats.elapsed = game.time - runStart, Sound.play('victory'), set all? input.attackHeld=false. Maybe hide controls? Show overlay after delay; hide controls immediately? Controls can fade. We can call hide controls in showVictory. Keep until overlay. 
  - Do not instantly show overlay. `game.mode='victory'`.
  - Update ambient/particles still. In update, if mode victory: update drops, particles, camera, ambient, overlayDelay; if <=0 call showVictoryScreen once. Need flag `overlayShown`.
- Player death:
```
function damagePlayer(amount, source) {
 const p=...;
 if mode!=='playing'||p.dead||p.invuln>0 return;
 p.hp=max(0,p.hp-amount); p.invuln=..., p.hurtFlash=.4; game.damageFlash=.5;
 stats.damageTaken+=amount;
 addFloater...
 spawn...
 camera.shake...
 Sound.play('hurt');
 if source { p.knockVX = cos(angle)*180? direction away from source }
 if hp<=0 killPlayer();
 updateHud();
}
```
- For enemy strike direction: knock away from enemy. Calculate before damage. Use source.x/y.
- `killPlayer`: p.dead=true; mode='dead'; overlayDelay=1.15; Sound.play('defeat'); input.attackHeld=false; show toast? Overlay.
- `update` handling modes:
```
function updateGame(dt) {
 game.time += dt;
 updateAmbient(dt);
 if (game.mode === 'playing') {
   updatePlayer(dt);
   updateEnemies(dt);
   updateDrops(dt);
   updatePickups...
   updateChest...
   updateParticles(dt); updateFloaters; updateSlashes;
   updateCamera(dt);
   updateInteract...
   checkVictory? invoked by kill
 } else if (game.mode === 'victory') {
   updateDrops(dt); updateParticles; updateFloaters; updateSlashes; updateCamera; updateChest open anim;
   game.overlayDelay -= dt;
   if (game.overlayDelay <=0 && !game.overlayShown) { game.overlayShown=true; showVictoryScreen(); }
 } else if (game.mode === 'dead') {
   p.deathT += dt;
   updateParticles; ... camera; overlayDelay...
   if ... showGameOverScreen();
 }
 // menu: update ambient, camera maybe slow drift, leaves.
}
```
- In menu, `game.time += dt`, update ambient; maybe camera slowly pans? Keep camera at player; tree sway. We can set camera target to player with slight sway. fine.
- update camera always.
- update interact button: in main `updateHud` maybe. We'll call `updatePrompt()` from logic or main. Define in main but call from update? Function global. `updateContextButton()` sets visibility based on chest/player/mode. Could be called each frame. Fine.
- `updateHud` each frame? Could call only when changes. But for health smooth transition and potion count, call when needed. Attack cooldown not shown. Fine.
- We'll call updateHud in reset, damage, potion, pickup, chest, kills. And on start. Also update prompt each frame.

- updateEnemies:
```
const p=game.player;
for each e:
 if e.dead { e.deathT += dt; if e.deathT>1.2... keep } continue;
 e.hitFlash...
 e.attackCooldown...
 if e.knock...
 if !p.dead:
   const d=dist(e,p); const a=angleTo(e,p)
   switch e.state...
 else state idle...
 apply separation
```
- knockback movement and friction: e.knockVX *= exp(-dt*7) etc. Apply move.
- state machine:
  - idle: wander around home:
    - e.wanderT -= dt; if <=0: e.wanderT=rand(1.4,3.2); e.wanderAngle = rand(0,TAU); maybe bias to home if far > 90: angle home.
    - if d < e.aggro && p alive -> e.state='chase'; e.alertT=3; maybe if e.type wolf play howl? no.
    - else move slow (0.28 speed) in wander angle. If dist from home > 100, wanderAngle toward home.
  - chase:
    - if p.dead -> idle.
    - face lerp to player.
    - if d > e.aggro*1.65 maybe still chase; fine.
    - if d <= e.range and e.attackCooldown<=0 -> windup
    - else move toward player; if wolf add strafe. For goblin maybe zigzag; no.
    - if d < e.range*0.52 and cooldown>0: back off slightly? For orc maybe. Could add.
    - Move at e.speed. Use separation.
  - windup:
    - no move; face toward player; `e.windupT -= dt`; maybe lunge after 0.65? 
    - if e.windupT <=0: enemyStrike(e)
  - recover: e.stateT -=dt; if goblin -> retreat else chase
  - retreat: move away for 0.5s then chase.
  - Add if e.type wolf and state chase: when d<e.range*1.5 and attackCooldown>0.3, strafe.
- separation among enemies:
```
for i<j if dist < r1+r2+6 push apart
```
Apply once after all updates maybe. Use moveEntity. Fine.
- Enemy stuck detection? No.
- Enemy facing initially toward player or random.
- During windup, draw telegraph. If player moves out of range, strike misses.
- `enemyStrike(e)`:
```
const p=game.player;
e.attackCooldown=e.cooldown;
e.state='recover'; e.stateT=e.type==='goblin'?0.4:0.32;
const d=dist(e,p); const facingA=angleTo(e,p); 
game.slashes.push({x:e.x+cos(e.facing)*e.r...});
Sound.play('enemyAttack');
if (!p.dead && d <= e.range + p.r + 8 && Math.abs(angleDelta(e.facing, facingA)) < 1.05) {
  damagePlayer(e.damage, e);
  if (e.type==='orc') p.knock...
}
```
- Important damagePlayer calculates knock direction from source.
- Recover state after strike.
- If player is dead, stop windup? fine.

- Player knockback direction:
```
if (source) { const a=angleTo(source.x,source.y,p.x,p.y); p.knockVX += cos(a)*(e.type==='orc'?240:140); ...}
```
- In damagePlayer signature `source` object. Use source.x.
- Enemy attack maybe gives brief slow? no.

- Update chest open timer: `chest.openT = min(1, openT+dt*3)`. Particles maybe initial only.
- Update chest glow.

- Pickups: world potions. Check dist < p.r + 20. Collect.
  - Remove from array with splice or mark. Use `collected=true` and filter? Simpler remove via `game.pickups = game.pickups.filter`. Each frame okay.
  - `game.inventory.potions++;` show toast `Healing Potion +1`; add floater; particles; Sound.play('potion').
- Chest open:
```
function openChest() {
 if chest.opened or mode!='playing' return;
 if dist > 88 { showToast('Move closer to the chest'); Sound.play('deny'); return; }
 chest.opened=true; chest.openT=0;
 game.camera.shake=.3;
 spawnParticles...
 Sound.play('chest');
 const reward=rollChestReward();
 game.chestReward=reward;
 showToast(`Chest: ${reward.label}`, reward.icon);
 addFloater...
 updateHud();
}
```
- `rollChestReward` details, returns {label, icon, kind}. Add relic if needed.
- For potions reward: inv.potions +=2.
- For gold: amount random 30-65; inv.gold += amount.
- For silver: inv.swordBonus +=6; inv.swordName = 'Silver Edge'; addRelic('silver-edge','⚔️','Silver Edge','+6 sword damage'); show sword stat update.
- For vitality: inv.maxHpBonus +=25; p.maxHp +=25; p.hp = min(max,hp+25); addRelic('heart','❤️','Vitality Charm','+25 max health');
- For ruby: inv.gold +=60; addRelic('ruby','💎','Ancient Ruby','A priceless ruby');
