  const bottom = w < 760 ? 142 : 108;
  const targets = [];

  for (const e of game.enemies) {
    if (!e.dead) targets.push({ x: e.x, y: e.y, color: '#ff7462', size: 7, pulse: 0 });
  }
  if (game.chest && !game.chest.opened) {
    targets.push({ x: game.chest.x, y: game.chest.y, color: '#ffdc7c', size: 6.5, pulse: 1 });
  }

  for (const t of targets) {
    const sx = (t.x - cam.x) * zoom + w / 2;
    const sy = (t.y - cam.y) * zoom + h / 2;
    if (sx > mx && sx < w - mx && sy > top && sy < h - bottom) continue;

    const cx = clamp(sx, mx, w - mx);
    const cy = clamp(sy, top, h - bottom);
    const angle = Math.atan2(sy - h / 2, sx - w / 2);
    const pulse = t.pulse ? 0.7 + Math.sin(game.time * 2.6) * 0.26 : 1;

    c.save();
    c.translate(cx, cy);
    c.rotate(angle);
    c.globalAlpha = 0.9 * pulse;

    const halo = c.createRadialGradient(0, 0, 0, 0, 0, 21);
    halo.addColorStop(0, t.color.replace(')', ', 0.22)').replace('rgb', 'rgba').replace('#', 'rgba('));
    c.restore();
  }
}

