    danger.addColorStop(1, `rgba(180, 20, 20, ${red})`);
    c.fillStyle = danger;
    c.fillRect(0, 0, w, h);
    c.restore();
  }

  if (game.victoryFlash > 0) {
    c.save();
    const victory = c.createRadialGradient(w * 0.5, h * 0.42, 0, w * 0.5, h * 0.42, Math.max(w, h) * 0.76);
    victory.addColorStop(0, `rgba(255, 237, 170, ${game.victoryFlash * 0.075})`);
