input.newString:
// ------------------------------------------------------------------- loop

let accumulator = 0;
const FIXED_STEP = 1 / 60;

function frame(now) {
  const elapsed = clamp((now - lastFrame) / 1000, 0, 0.25);
  lastFrame = now;
  accumulator = Math.min(accumulator + elapsed, 0.25);
  let steps = 0;
  while (accumulator >= FIXED_STEP && steps < 10) {
    updateGame(FIXED_STEP);
    accumulator -= FIXED_STEP;
    steps += 1;
  }
  if (steps === 10) accumulator = 0;
  renderGame();
  requestAnimationFrame(frame);
}

function init() {
  resizeGame();
  resetGame();
  prepareWorldSprites();
  buildScreenOverlays();
  updateHud(true);
  updateContextButton();
  bindControls();

