import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const home = process.env.HOME
const runtime = join(home, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true })
await page.goto('http://localhost:3000/', { waitUntil: 'load' })
await page.locator('#play-btn').tap()
await page.waitForTimeout(600)
const info = await page.evaluate(() => {
  const sel = ['.hud', '.hud-top', '.player-panel', '.satchel', '.satchel-row', '.relic-list']
  const out = { inner: innerWidth, scroll: document.documentElement.scrollWidth }
  for (const s of sel) {
    const el = document.querySelector(s)
    const r = el.getBoundingClientRect()
    out[s] = { x: r.x, y: r.y, w: r.width, h: r.height, right: r.right, sw: el.scrollWidth, cw: el.clientWidth }
  }
  out.chips = [...document.querySelectorAll('.inv-chip')].map(el => { const r = el.getBoundingClientRect(); return { text: el.textContent.trim(), x: r.x, w: r.width, right: r.right } })
  return out
})
console.log(JSON.stringify(info, null, 2))
await browser.close()

