import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const home = process.env.HOME
const runtime = join(home, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
for (const width of [320, 360, 390, 430, 760]) {
  const page = await browser.newPage({ viewport: { width, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true })
  await page.goto('http://localhost:3000/', { waitUntil: 'load' })
  await page.locator('#play-btn').tap()
  await page.waitForTimeout(500)
  const info = await page.evaluate(() => {
    const vals = document.querySelectorAll('.chip-value')
    vals[0].textContent = '999'
    vals[1].textContent = '99'
    vals[2].textContent = '184'
    const top = document.querySelector('.hud-top').getBoundingClientRect()
    const pp = document.querySelector('.player-panel').getBoundingClientRect()
    const sat = document.querySelector('.satchel').getBoundingClientRect()
    const chips = [...document.querySelectorAll('.inv-chip')].map(el => {
      const r = el.getBoundingClientRect()
      return { w: +r.width.toFixed(1), right: +r.right.toFixed(1), overflow: el.scrollWidth - el.clientWidth }
    })
    return { inner: innerWidth, scroll: document.documentElement.scrollWidth, top: { x: top.x, w: top.width, right: top.right }, pp: { w: pp.width, right: pp.right }, sat: { x: sat.x, w: sat.width, right: sat.right }, chips }
  })
  await page.screenshot({ path: `/tmp/opencode/hw-shots/hud-${width}.png`, clip: { x: Math.max(0, width - 180), y: 0, width: Math.min(180, width), height: 90 } })
  console.log(width, JSON.stringify(info))
  await page.close()
}
await browser.close()

